tests:
test('counts repeated words', () => { assert.deepEqual(wordCount('the cat and the hat'), { the: 2, cat: 1, and: 1, hat: 1 }); });
test('ignores case', () => { assert.deepEqual(wordCount('Go go GO'), { go: 3 }); });
test('single word', () => { assert.deepEqual(wordCount('hello'), { hello: 1 }); });
test('empty string gives empty object', () => { assert.deepEqual(wordCount(''), {}); });

referenceSolution:
function wordCount(sentence) {
  const counts = {};
  if (sentence === '') {
    return counts;
  }
  for (const word of sentence.toLowerCase().split(' ')) {
    counts[word] = (counts[word] || 0) + 1;
  }
  return counts;
}
